with base as (select id, account_id, txn_type, is_flagged, round(amount * 0.9, 2) as adjusted_amount from transactions where txn_time >= timestamp '2023-07-02 15:00:00' and merchant is not null), enriched as (select id, account_id, is_flagged, lead(adjusted_amount) over (partition by txn_type, account_id order by adjusted_amount, id) as next_adjusted_amount, row_number() over (partition by txn_type, account_id order by adjusted_amount, id) as seq_no, rank() over (partition by account_id order by adjusted_amount desc) as adjusted_amount_rank from base), scored as (select *, max(next_adjusted_amount) over (partition by account_id order by adjusted_amount_rank, id rows between unbounded preceding and current row) as running_max_next_adjusted_amount, count(next_adjusted_amount) over (partition by account_id order by adjusted_amount_rank, id rows between unbounded preceding and current row) as running_count_next_adjusted_amount, avg(next_adjusted_amount) over (partition by account_id order by adjusted_amount_rank, id rows between unbounded preceding and current row) as running_avg_next_adjusted_amount, min(next_adjusted_amount) over (partition by account_id order by adjusted_amount_rank, id rows between unbounded preceding and current row) as running_min_next_adjusted_amount from enriched where seq_no between 3 and 5), scored_transactions as (select *, rank() over (partition by account_id order by seq_no desc nulls last) as seq_no_rank, ntile(5) over (partition by account_id order by seq_no, id) as seq_no_bucket from scored), latest as (select * from (select *, row_number() over (partition by account_id order by seq_no nulls last, id) as dedup_rank from scored_transactions) ranked where dedup_rank = 1), scored_transactions_2 as (select *, min(running_avg_next_adjusted_amount) over (partition by account_id) as account_id_min_running_avg_next_adjusted_amount, round(seq_no_bucket / sum(seq_no_bucket) over (partition by account_id), 4) as seq_no_bucket_share, row_number() over (partition by account_id order by running_max_next_adjusted_amount desc, id) as row_seq, rank() over (partition by account_id order by running_avg_next_adjusted_amount desc nulls last) as running_avg_next_adjusted_amount_rank, avg(adjusted_amount_rank) over (partition by account_id order by seq_no, id rows between 5 preceding and current row) as adjusted_amount_rank_avg_5 from latest), latest_transactions as (select * from (select *, row_number() over (partition by account_id order by account_id_min_running_avg_next_adjusted_amount desc, id) as row_num from scored_transactions_2) t where row_num = 1) select seq_no, percentile_approx(adjusted_amount_rank, 0.9) as adjusted_amount_rank_p90, count(distinct id) as distinct_ids, approx_percentile(seq_no_bucket, 0.95) as seq_no_bucket_p95, percentile_approx(running_avg_next_adjusted_amount_rank, 0.5) as running_avg_next_adjusted_amount_rank_p50, percentile_approx(seq_no_bucket_share, array(0.25, 0.5, 0.75)) as seq_no_bucket_share_quartiles, percentile_approx(account_id_min_running_avg_next_adjusted_amount, 0.9) as account_id_min_running_avg_next_adjusted_amount_p90 from latest_transactions group by rollup (seq_no) order by distinct_ids desc;
